            goal: 'Crear una marca premium de SUP de pesca de 2 SKUs (11\'0" Guide Pro y 12\'6" Expedition Elite) con características de pesca integradas, dirigida a clientes DTC y otros guías de pesca, con un objetivo del primer año de 400 unidades vendidas y $320,000 en ingresos.',
