            goal: 'Lanzar un conjunto de 5 rutas SUP mapeadas por GPS accesibles mediante una plataforma de concierge móvil, generando 8,000 reservas pagadas (EUR 65-EUR 95 por persona) en la primera temporada de 12 meses.',
