            background:
              'La Amazon Research Association (ARA), una organización sin fines de lucro que realiza estudios de ecología de agua dulce en la Amazonía peruana, opera 6 estaciones de investigación de campo a lo largo de los ríos Ucayali y Marañón. La Investigadora de Campo Principal Dra. Sofía Huamán había dependido de botes de aluminio con motores fuera de borda de 25 hp para estudios de transectos de delfines de río (Inia geoffrensis) y nutrias gigantes (Pteronura brasiliensis). Sin embargo, un estudio acústico de 2023 reveló que el ruido del motor causaba una reducción de 47% en avistamientos superficiales de delfines a menos de 500 m de la embarcación durante el muestreo. Adicionalmente, la logística de combustible para estaciones remotas costaba $1,240 mensuales y requería viajes redondos de 3 horas en canoa de abastecimiento. Huamán necesitaba una plataforma silenciosa, de cero emisiones y portátil capaz de transportar 2 investigadores más 40 kg de equipamiento de muestreo en jornadas de estudio de 8 horas.',
