            goal: "Desarrollar un paquete de 'Experiencia SUP de Cenote a Océano de Firma' (tour guiado de 3 horas, fotografía profesional y menú de degustación mexicano) a $450/persona con margen mínimo del 40% y calificación de satisfacción de huéspedes de 4.8+.",
