              "La 'Colección Azure' opera 4 resorts de lujo en las Maldivas: Azure North (Atolón Malé Norte), Azure South (Atolón Malé Sur), Azure Private Island (Atolón Baa) y Azure Retreat (Atolón Raa). Su directora grupal de bienestar, Simone Devereux, de 39 años, ex instructora profesional de yoga de Australia, llevaba 7 años con Azure. En 2022, Simone encuestó a 2,800 huéspedes en las 4 propiedades y encontró que el 73% expresaba interés en clases de SUP yoga, pero solo el 12% reservaba realmente — siendo la principal barrera la 'falta de confianza en una tabla estrecha' (citada por el 64% de los no reservantes). La flota existente de SUP (tablas de 3 años de un OEM genérico chino) era de 14 tablas en total, adecuadas para remo en aguas tranquilas pero inestables para yoga: tablas de 32\" de ancho con cubiertas EVA resbaladizas. Simone necesitaba una flota de tablas SUP yoga construidas a propósito con ancho extra, superficie de cubierta acolchada y antideslizante adecuada para práctica descalzo, y capacidad de soportar hasta 350 libras para posturas de yoga en pareja.",
            goal: 'Desplegar una flota de 40 tablas especializadas de SUP yoga en 4 resorts, desarrollar un programa escalonado de SUP yoga (Principiante, Intermedio, Avanzado, En Pareja) con instructores capacitados, y aumentar la conversión de reservas de SUP yoga del 12% al 35% en 12 meses.',
